# Meridian Credits

A Python standard-library JSON CLI for monthly loyalty-credit statements.

Run `python3 main.py` with one request on stdin. Check the starter with `python3 -m unittest discover -s tests`. Feature issues supply their interfaces and approved business agreements.

Run only introduced public suites with `python3 test_public.py --cases PATH`. Suite names and explicit requests identify their release; a change to the current agreement does not invalidate an explicit earlier-release suite.

MAIN
#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

TESTS
"""Run one supplied public case file against the local application/artifacts."""
import argparse
import json
from pathlib import Path
import subprocess
import sys


def equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(equal(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(equal(a, b) for a, b in zip(left, right))
    return left == right


parser = argparse.ArgumentParser()
parser.add_argument("--cases", required=True)
args = parser.parse_args()
failed = 0
for case in json.loads(Path(args.cases).read_text()):
    try:
        if "artifact_json_path" in case:
            got = json.loads(Path(case["artifact_json_path"]).read_text())
        else:
            proc = subprocess.run([sys.executable, "main.py"], input=json.dumps(case["request"]),
                                  capture_output=True, text=True, check=True, timeout=5)
            got = json.loads(proc.stdout)
        ok = equal(got, case["expected"])
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        ok = False
        got = str(exc)
    print(("PASS " if ok else "FAIL ") + case["name"])
    if not ok:
        print(" expected:", case["expected"])
        print(" received:", got)
        failed += 1
raise SystemExit(bool(failed))
import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]


class SmokeTests(unittest.TestCase):
    def check_request(self, request, expected):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps(request), text=True, capture_output=True, check=True)
        self.assertEqual(json.loads(got.stdout), expected)

    def test_ping(self):
        self.check_request({"command": "ping"}, {"status": "ok", "product": "Meridian Credits"})

    def test_unknown(self):
        self.check_request({"command": "unknown"}, {"error": "unknown_command"})

